source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    row_lines = []
    for r, row in enumerate(grid):
        counts = {}
        for v in row:
            counts[v] = counts.get(v, 0) + 1
        if max((n for v, n in counts.items() if v != 0), default=0) >= w - 3:
            row_lines.append(r)
    col_lines = []
    for c in range(w):
        counts = {}
        for r in range(h):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
        if max((n for v, n in counts.items() if v != 0), default=0) >= h - 3:
            col_lines.append(c)
    rows = sorted(set([0] + row_lines + [r + 1 for r in row_lines if r + 1 < h]))
    cols = sorted(set([0] + col_lines + [c + 1 for c in col_lines if c + 1 < w]))
    return [[grid[r][c] for c in cols] for r in rows]
'''
